static inline uint32_t ECSynthMinU32(uint32_t a, uint32_t b)
{
    return a < b ? a : b;
}

static inline uint32_t ECSynthMaxU32(uint32_t a, uint32_t b)
{
    return a > b ? a : b;
}

static inline int32_t ECSynthClampI32(int32_t value, int32_t low, int32_t high)
{
    return value < low ? low : (value > high ? high : value);
}

static inline size_t ECSynthMinSize(size_t a, size_t b)
{
    return a < b ? a : b;
}

static inline uint16_t ECSynthToFraction(uint32_t value, uint32_t scale_max)
{
    if (value >= scale_max)
        return (uint16_t)kECSynthFractionMax;
    return (uint16_t)((value * kECSynthFractionMax + scale_max / 2) / scale_max);
}

static inline uint32_t ECSynthFromFraction(uint16_t fraction, uint32_t scale_max)
{
    return ((uint32_t)fraction * scale_max + kECSynthFractionMax / 2) / kECSynthFractionMax;
}

static inline uint16_t ECSynthLaneFraction(int32_t value)
{
    return (uint16_t)ECSynthClampI32(value, 0, (int32_t)kECSynthFractionMax);
}

static inline ECSynthByteReader ECSynthReader(const uint8_t *data, size_t size)
{
    ECSynthByteReader reader = {data, size, 0, 0};
    return reader;
}

static inline size_t ECSynthReaderRemaining(const ECSynthByteReader *reader)
{
    return reader->size - reader->position;
}

static inline int32_t ECSynthReaderAtEnd(const ECSynthByteReader *reader)
{
    return reader->position >= reader->size;
}

static inline const uint8_t *ECSynthReaderCurrent(const ECSynthByteReader *reader)
{
    return reader->data + reader->position;
}

static inline void ECSynthReaderSeek(ECSynthByteReader *reader, size_t position)
{
    if (position > reader->size)
    {
        reader->failed   = 1;
        reader->position = reader->size;
        return;
    }
    reader->position = position;
}

static inline void ECSynthReaderSkip(ECSynthByteReader *reader, size_t count)
{
    if (count > ECSynthReaderRemaining(reader))
    {
        reader->failed   = 1;
        reader->position = reader->size;
        return;
    }
    reader->position += count;
}

static inline uint8_t ECSynthReaderU8(ECSynthByteReader *reader)
{
    if (reader->position >= reader->size)
    {
        reader->failed = 1;
        return 0;
    }
    return reader->data[reader->position++];
}

static inline uint16_t ECSynthReaderU16LE(ECSynthByteReader *reader)
{
    const uint16_t low = ECSynthReaderU8(reader);
    return (uint16_t)(low | (ECSynthReaderU8(reader) << 8));
}

static inline uint32_t ECSynthReaderU32LE(ECSynthByteReader *reader)
{
    const uint32_t low = ECSynthReaderU16LE(reader);
    return low | ((uint32_t)ECSynthReaderU16LE(reader) << 16);
}

static inline uint16_t ECSynthReaderU16BE(ECSynthByteReader *reader)
{
    const uint16_t high = ECSynthReaderU8(reader);
    return (uint16_t)((high << 8) | ECSynthReaderU8(reader));
}

static inline uint32_t ECSynthReaderU32BE(ECSynthByteReader *reader)
{
    const uint32_t high = ECSynthReaderU16BE(reader);
    return (high << 16) | ECSynthReaderU16BE(reader);
}

static inline uint32_t ECSynthReaderVariableLength(ECSynthByteReader *reader)
{
    uint32_t value = 0;
    for (int32_t count = 0; count < 4; count++)
    {
        const uint8_t byte = ECSynthReaderU8(reader);
        value              = (value << 7) | (byte & 0x7F);
        if (!(byte & 0x80))
            return value;
    }
    reader->failed = 1;
    return value;
}

static inline const uint8_t *ECSynthReaderTake(ECSynthByteReader *reader, size_t count)
{
    if (count > ECSynthReaderRemaining(reader))
    {
        reader->failed   = 1;
        reader->position = reader->size;
        return NULL;
    }
    const uint8_t *const start = reader->data + reader->position;
    reader->position += count;
    return start;
}

static inline void ECSynthReaderCopy(ECSynthByteReader *reader, void *destination, size_t count)
{
    const uint8_t *const source = ECSynthReaderTake(reader, count);
    if (source)
        memcpy(destination, source, count);
}

static inline int32_t ECSynthReaderTag(ECSynthByteReader *reader, const char *tag, size_t length)
{
    if (ECSynthReaderRemaining(reader) < length || memcmp(reader->data + reader->position, tag, length) != 0)
        return 0;
    reader->position += length;
    return 1;
}

