// Exponential tables for envelopes and volumes scales

static float exp_env[100], exp_vol[100], exp_vol_op[100];

static inline float LerpVolumeTable(const float *table, float volume)
{
    const float    clamped = ClampFloat(volume, 0, 99);
    const uint32_t index   = (uint32_t)clamped;
    if (index >= 99)
        return table[99];
    return table[index] + (table[index + 1] - table[index]) * (clamped - (float)index);
}

