void ECSynthDefaultGeneralMidi(ECSynthGeneralMidi *general_midi)
{
    memset(general_midi, 0, sizeof(*general_midi));
    for (uint32_t i = 0; i < kECSynthGeneralMidiProgramCount; i++)
    {
        if (kDefaultBankMelodic[i] != kDefaultBankNone)
        {
            memcpy(&general_midi->melodic[i], kDefaultBankInstruments[kDefaultBankMelodic[i]],
                   kECSynthInstrumentFileSize);
            general_midi->has_melodic[i] = 1;
        }
        if (kDefaultBankPercussion[i] != kDefaultBankNone)
        {
            memcpy(&general_midi->percussion[i], kDefaultBankInstruments[kDefaultBankPercussion[i]],
                   kECSynthInstrumentFileSize);
            general_midi->has_percussion[i] = 1;
        }
    }
}

