static float *ECSynthBuildOrgWave(uint32_t w)
{
    float *const table = malloc(6 * kWavetableSize * sizeof(float));
    if (!table)
        return wavetable[0];

    for (uint32_t level = 0; level < 6; level++)
    {
        const uint32_t n    = 256 >> level;
        const uint32_t step = 256 / n;
        for (uint32_t i = 0; i < kWavetableSize; i++)
        {
            const float    pos                = (float)i * n / kWavetableSize;
            const uint32_t j                  = (uint32_t)pos;
            table[level * kWavetableSize + i] = ECSynthLagrange(
                kOrgWaves[w][((j + n - 1) % n) * step] / 128.f, kOrgWaves[w][(j % n) * step] / 128.f,
                kOrgWaves[w][((j + 1) % n) * step] / 128.f, kOrgWaves[w][((j + 2) % n) * step] / 128.f, pos - j);
        }
    }
    return ECSynthPublishTable(&org_wavetable[w], table);
}

static float *ECSynthBuildOrgDrum(uint32_t w)
{
    const int8_t  *src   = kOrgDrumData;
    const uint32_t len   = kOrgDrumLength[w];
    float *const   table = calloc(ECSynthOrgDrumSize(w), sizeof(float));
    if (!table)
        return wavetable[0];

    for (uint32_t i = 0; i < w; i++)
        src += kOrgDrumLength[i];

    for (uint32_t i = 0; i < 2 * len; i++)
    {
        const uint32_t j = i / 2;
        table[i] =
            ECSynthLagrange(j >= 1 ? src[j - 1] / 128.f : 0, src[j] / 128.f, j + 1 < len ? src[j + 1] / 128.f : 0,
                            j + 2 < len ? src[j + 2] / 128.f : 0, (i & 1) * 0.5f);
    }
    return ECSynthPublishTable(&org_drum_wavetable[w], table);
}
